@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --font-sans: var(--font-sans);
  --font-heading: var(--font-sans);
  --font-mono: var(--font-mono);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
}

/* the a432 settings: the theme hue 72 (432 mod 360), the chart colours the harmonics 432, 216, 108, 54, 27 Hz, the radius 0.432rem (432 / 1000) */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: hsl(72 62% 44%);
  --primary-foreground: hsl(72 62% 98%);
  --secondary: hsl(72 30% 96%);
  --secondary-foreground: hsl(72 62% 20%);
  --muted: oklch(0.97 0 0);
  --muted-foreground: oklch(0.556 0 0);
  --accent: hsl(72 40% 94%);
  --accent-foreground: hsl(72 62% 20%);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.922 0 0);
  --input: oklch(0.922 0 0);
  --ring: hsl(72 62% 44%);
  --chart-1: hsl(72 62% 50%);
  --chart-2: hsl(216 62% 50%);
  --chart-3: hsl(108 62% 50%);
  --chart-4: hsl(54 62% 50%);
  --chart-5: hsl(27 62% 50%);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: hsl(72 62% 44%);
  --sidebar-primary-foreground: hsl(72 62% 98%);
  --sidebar-accent: hsl(72 40% 94%);
  --sidebar-accent-foreground: hsl(72 62% 20%);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: hsl(72 62% 44%);
  --radius: 0.432rem;
}

.dark {
  --background: oklch(0.145 0 0);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.205 0 0);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.205 0 0);
  --popover-foreground: oklch(0.985 0 0);
  --primary: hsl(72 62% 56%);
  --primary-foreground: hsl(72 62% 10%);
  --secondary: hsl(72 20% 18%);
  --secondary-foreground: hsl(72 40% 92%);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.708 0 0);
  --accent: hsl(72 30% 22%);
  --accent-foreground: hsl(72 40% 92%);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(1 0 0 / 10%);
  --input: oklch(1 0 0 / 15%);
  --ring: hsl(72 62% 56%);
  --chart-1: hsl(72 62% 60%);
  --chart-2: hsl(216 62% 60%);
  --chart-3: hsl(108 62% 60%);
  --chart-4: hsl(54 62% 60%);
  --chart-5: hsl(27 62% 60%);
  --sidebar: oklch(0.205 0 0);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: hsl(72 62% 56%);
  --sidebar-primary-foreground: hsl(72 62% 10%);
  --sidebar-accent: hsl(72 30% 22%);
  --sidebar-accent-foreground: hsl(72 40% 92%);
  --sidebar-border: oklch(1 0 0 / 10%);
  --sidebar-ring: hsl(72 62% 56%);
}

@layer base { * { @apply border-border outline-ring/50; } body { @apply bg-background text-foreground; } }

/* the a432 stylesheet: every QPU block draws itself from its address */
:root {
  --a432-key: 432;
  --a432-hue: 72;
  --a432-1: hsl(72 62% 44%);
  --a432-2: hsl(216 62% 52%);
  --a432-3: hsl(108 62% 60%);
  --a432-4: hsl(54 62% 68%);
  --a432-5: hsl(27 62% 76%);
  --a432-accent: hsl(72 62% 44%);
  --qpu-coin: hsl(72 62% 44%);
  --qpu-coil: hsl(120 62% 44%);
  --qpu-coil-cmyk: 1 0 1 0;
}
/* every block draws itself from the custom properties its UUID set on its root; nothing here needs a script */
.qpu-block { border-left: 3px solid var(--qpu-accent, var(--a432-accent)); padding-left: var(--pad-sm, 8px); content-visibility: auto; contain-intrinsic-size: auto 240px; background: linear-gradient(90deg, color-mix(in oklab, var(--qpu-accent, var(--a432-accent)) 6%, transparent), transparent 60%); }
.qpu-block::before { content: ''; display: block; height: 3px; margin-bottom: var(--gap-sm, 6px); background: conic-gradient(from calc(var(--qpu-angle, 0) * 1deg) at 50% 120%, var(--qpu-accent, var(--a432-accent)), var(--qpu-tail, var(--a432-2)), var(--qpu-accent, var(--a432-accent))); }
.qpu-block [data-status] { border-left: 2px solid var(--qpu-status, var(--a432-3)); padding-left: 4px; }
.qpu-block [data-status="served"] { --qpu-status: var(--a432-1); } .qpu-block [data-status="partial"] { --qpu-status: var(--a432-2); } .qpu-block [data-status="open"] { --qpu-status: var(--a432-3); } .qpu-block [data-status="blocked"], .qpu-block [data-status="out_of_scope"] { --qpu-status: var(--a432-5); }
@media (prefers-reduced-motion: no-preference) { .qpu-block::before { animation: qpu-vortex var(--qpu-period, 3888ms) linear infinite; } @keyframes qpu-vortex { to { filter: hue-rotate(360deg); } } }
@media (prefers-color-scheme: dark) { .qpu-block { background: linear-gradient(90deg, color-mix(in oklab, var(--qpu-accent, var(--a432-accent)) 12%, transparent), transparent 60%); } }
@media print { .qpu-block::before { animation: none; } }
/* the program presented by hue, moved by the params: the ten steps as a ring, rotated by the shift the params gave */
.qpu-program { background: var(--qpu-program); border-radius: 50%; aspect-ratio: 1; width: 3em; transform: rotate(calc(var(--qpu-shift, 0) * 1deg)); }
/* the scannable stream: the block's frames stepped through at the vortex period, one character a frame; a single frame links nothing, a stream reads the address */
.qpu-scan { background-image: var(--qpu-frames); background-size: 3600% 100%; background-repeat: no-repeat; animation: qpu-scan var(--qpu-period, 3888ms) steps(36, end) infinite; min-height: 1.5em; } @keyframes qpu-scan { to { background-position: 100% 0; } }
/* randomness in CSS: a random delay where the engine has random(); the device's sampled phase where it set one */
@supports (animation-delay: random(0ms, 1ms)) { .qpu-block::before, .qpu-scan { animation-delay: random(0ms, 3888ms); } }
.qpu-block[data-phase]::before, .qpu-scan[data-phase] { animation-delay: calc(var(--qpu-phase, 0) * -1ms); }
/* when coins fuse to coils the block turns green: the heart chakra, computed from the key */
.qpu-block[data-coil] { --qpu-accent: var(--qpu-coil); } .qpu-block[data-coin] { --qpu-accent: var(--qpu-coin); }
.qpu-rays { background: conic-gradient(from calc(var(--qpu-angle, 0) * 1deg), var(--qpu-accent, var(--a432-accent)) 0deg 6deg, transparent 6deg 60deg, var(--qpu-accent, var(--a432-accent)) 60deg 66deg, transparent 66deg 120deg, var(--qpu-accent, var(--a432-accent)) 120deg 126deg, transparent 126deg 180deg, var(--qpu-accent, var(--a432-accent)) 180deg 186deg, transparent 186deg 240deg, var(--qpu-accent, var(--a432-accent)) 240deg 246deg, transparent 246deg 300deg, var(--qpu-accent, var(--a432-accent)) 300deg 306deg, transparent 306deg 360deg); }
.qpu-rays::after, .qpu-block[data-rays]::after { content: var(--qpu-signal, '') ' ' var(--qpu-signal-reflected, '') ' · ' var(--qpu-signal-digits, ''); font-family: serif; letter-spacing: 0.1em; }
.qpu-gateways { background: conic-gradient(from calc(var(--qpu-angle, 0) * 1deg), var(--qpu-ink, currentColor) 0deg 3deg, transparent 3deg 90deg, var(--qpu-ink, currentColor) 90deg 93deg, transparent 93deg 180deg, var(--qpu-ink, currentColor) 180deg 183deg, transparent 183deg 270deg, var(--qpu-ink, currentColor) 270deg 273deg, transparent 273deg 360deg); }
